RSpec.describe "Gateway forwarded destroy honours the looked-up version", type: :request do
  let(:company) { create(:company) }
  let(:user) { create(:user, current_workspace_id: company.id) }
  let(:project) { create(:project, billable: true, client: create(:client, company:)) }
  let(:fake) { TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key) }

  around do |example|
    with_timekeeping_env(Timekeeping::UserToken::PRIVATE_KEY_ENV, timekeeping_key_pair.to_pem) do
      with_timekeeping_env(Timekeeping::EntryApiClient::BASE_URL_ENV, "http://timekeeping.test") { example.run }
    end
  end

  before do
    create(:employment, company:, user:)
    user.add_role :admin, company
    TimekeepingOwnership.current.update!(owner: "timekeeping", generation: 2, handoff_step: nil)
    fake.generation = 2
    fake.register_company(id: company.id, edit_days: company.timesheet_edit_days)
    fake.register_user(id: user.id, company_id: company.id, role: "admin")
    fake.register_project(id: project.id, company_id: company.id)
    route_timekeeping_to_fake(fake, base_url: "http://timekeeping.test")
    sign_in user
  end

  it "a forwarded destroy of an entry whose version changed after lookup answers 409 and leaves it undiscarded" do
    entry_id = fake.add_entry(company_id: company.id, user_id: user.id, project_id: project.id,
                              work_date: Date.current.iso8601, duration: 45.0, note: "Original").fetch("id")
    looked_up_versions = []
    allow(Timekeeping::EntryApiClient).to receive(:new).and_wrap_original do |original, *args, **kwargs|
      client = original.call(*args, **kwargs)
      allow(client).to receive(:show_entry).and_wrap_original do |show, **show_kwargs|
        row = show.call(**show_kwargs)
        looked_up_versions << row["version"]
        # Another writer changes the entry between the lookup and the delete.
        other_writer_token = Timekeeping::UserToken.mint(user:, company:)
        fake.call("PATCH", "/v1/companies/#{company.id}/entries/#{entry_id}",
                  headers: { "Authorization" => "Bearer #{other_writer_token}", "Ownership-Generation" => "2",
                             "Idempotency-Key" => "gateway-version-other-writer" },
                  body: { "note" => "Changed elsewhere" })
        row
      end
      client
    end

    send_request :delete, api_v1_timesheet_entry_path(entry_id), headers: auth_headers(user)

    expect(response).to have_http_status(:conflict)
    expect(response.parsed_body["reason"]).to eq("version_conflict")
    expect(fake.stored_entry(entry_id)["discarded_at"]).to be_nil
    delete_request = fake.requests.find { |request| request[:method] == "DELETE" }
    expect(looked_up_versions.size).to eq(1)
    expect(delete_request[:headers]["If-Match"]).to eq(looked_up_versions.first.to_s)
  end
end

# "A missing row or an unknown owner also refuses (fail closed). It never falls back to legacy and never answers 404."
# Create, update and destroy each reach the refusal through their own gateway method, and only update and destroy
# look an entry up, so each verb keeps its own example of the one missing-row contract.
RSpec.describe "Api::V1::TimesheetEntry gateway missing ownership row", type: :request do
  let(:missing_row_company) { create(:company) }
  let(:missing_row_project) { create(:project, billable: true, client: create(:client, company: missing_row_company)) }
  let(:missing_row_employee) { missing_row_member(:employee) }
  let(:missing_row_admin) { missing_row_member(:admin) }

  def missing_row_member(role)
    create(:user, current_workspace_id: missing_row_company.id).tap do |user|
      create(:employment, company: missing_row_company, user:)
      user.add_role role, missing_row_company
    end
  end

  def delete_missing_row_ownership
    TimekeepingOwnership.where(id: TimekeepingOwnership::SINGLETON_ID).delete_all
  end

  def expect_missing_row_refusal
    expect(response).to have_http_status(:service_unavailable)
    expect(json_response["reason"]).to eq("ownership_moving")
    expect(response.headers["Retry-After"]).to be_present
    expect(TimekeepingOwnership.where(id: TimekeepingOwnership::SINGLETON_ID)).to be_empty
    expect(TimekeepingOwnership.count).to eq(0)
  end

  # "A missing row or an unknown owner also refuses (fail closed). It never falls back to legacy and never answers 404."
  # Each verb is its own example: only update and destroy look the entry up, so only they could answer 404.
  it "refuses a create by an employee with 503 ownership_moving and writes no entry" do
    delete_missing_row_ownership
    sign_in missing_row_employee
    params = {
      project_id: missing_row_project.id,
      timesheet_entry: { duration: 30, work_date: Date.current, note: "No row", bill_status: :unbilled }
    }

    expect do
      send_request :post, api_v1_timesheet_entry_index_path, params:, headers: auth_headers(missing_row_employee)
    end.not_to change(TimesheetEntry, :count)

    expect_missing_row_refusal
  end

  it "refuses an update by an admin with 503 and not 404, leaving the note unchanged" do
    entry = create(:timesheet_entry, user: missing_row_admin, project: missing_row_project,
      work_date: Date.current, note: "Before")
    delete_missing_row_ownership
    sign_in missing_row_admin

    expect do
      send_request :patch, api_v1_timesheet_entry_path(entry), params: {
        project_id: missing_row_project.id,
        timesheet_entry: { duration: 30, work_date: Date.current, note: "After", bill_status: :unbilled }
      }, headers: auth_headers(missing_row_admin)
    end.not_to change(TimesheetEntry, :count)

    expect_missing_row_refusal
    expect(entry.reload.note).to eq("Before")
    expect(entry).not_to be_discarded
  end

  it "refuses a destroy by an admin with 503 and not 404, leaving the entry undiscarded" do
    entry = create(:timesheet_entry, user: missing_row_admin, project: missing_row_project, work_date: Date.current)
    delete_missing_row_ownership
    sign_in missing_row_admin

    expect do
      send_request :delete, api_v1_timesheet_entry_path(entry), headers: auth_headers(missing_row_admin)
    end.not_to change(TimesheetEntry, :count)

    expect_missing_row_refusal
    expect(entry.reload).not_to be_discarded
    expect(entry.discarded_at).to be_nil
  end
end

RSpec.describe "Api::V1::TimesheetEntry gateway legacy writer marker", type: :request, committed_data: true do
  let(:marker_company) { create(:company) }
  let(:marker_project) { create(:project, billable: true, client: create(:client, company: marker_company)) }
  let(:marker_user) do
    create(:user, current_workspace_id: marker_company.id).tap do |user|
      create(:employment, company: marker_company, user:)
      user.add_role :employee, marker_company
    end
  end

  # Reads the writer setting while the entry's after_create event fires,
  # which is inside the gateway's write transaction.
  let(:marker_probe) do
    Class.new do
      attr_reader :seen

      def emit(event)
        return unless event[:name] == "TimesheetEntries::Created"

        @seen = ActiveRecord::Base.connection.select_value("SELECT current_setting('miru.writer', true)")
      end
    end.new
  end

  # "A legacy write reads `current_setting('miru.writer', true)` as `legacy_gateway` from inside the write, and an empty value after commit."
  it "a legacy create runs as legacy_gateway inside the write, commits the entry, and leaves the setting empty after commit" do
    sign_in marker_user
    params = {
      project_id: marker_project.id,
      timesheet_entry: { duration: 45, work_date: Date.current, note: "Legacy marker", bill_status: :unbilled }
    }

    Rails.event.subscribe(marker_probe)
    begin
      send_request :post, api_v1_timesheet_entry_index_path, params:, headers: auth_headers(marker_user)
    ensure
      Rails.event.unsubscribe(marker_probe)
    end

    expect(response).to be_successful
    expect(json_response["notice"]).to match("Timesheet created")
    expect(marker_probe.seen).to eq("legacy_gateway")
    expect(TimesheetEntry.find(json_response["entry"]["id"]).note).to eq("Legacy marker")
    after_commit = ActiveRecord::Base.connection.select_value("SELECT current_setting('miru.writer', true)")
    expect(after_commit.to_s).to eq("")
  end
end

